def policy(obs, P):
    x,y,vx,vy,angle,ang_v,ll,lr = obs
    if abs(vx) > P['vx_big']:
        return 2
    if vy < P['vy_thr']:
        if x > P['x_thr_pos']:
            return 0
        if y > P['y_thr_high']:
            if x < P['x_high_neg']:
                return 0
            if angle < P['ang_high_neg']:
                return 1
            if angle > P['ang_high_pos']:
                return 3
            return 1
        if angle < P['ang_fall_neg']:
            return 1
        if angle > P['ang_fall_pos']:
            return 3
        if ang_v < -P['angv_thr']:
            return 3
        if ang_v > P['angv_thr']:
            return 1
        return 2
    if ll > 0.5 and lr > 0.5:
        if abs(vx) > P['vx_land_thr'] or vy < P['vy_land_thr']:
            return 2
        if angle < P['ang_land_neg']:
            return 1
        if angle > P['ang_land_pos']:
            return 3
        if x < P['x_land_neg']:
            return 3
        if x > P['x_land_pos']:
            return 0
        return 0
    if ll > 0.5 or lr > 0.5:
        if angle < P['ang_land_neg']:
            return 1
        if angle > P['ang_land_pos']:
            return 3
        return 0
    if vx <= P['vx_hover']:
        if angle <= P['ang_h_neg2']:
            return 1
        if angle <= P['ang_h_neg1']:
            return 0
        if angle <= P['ang_h_pos1']:
            return 3
        return 0
    if x <= P['x_hover_neg']:
        if vx <= P['vx_hover2']:
            return 3
        return 1
    if vx <= P['vx_hover3']:
        return 0
    return 1
